"""
Self-extracting package bootstrap for NAPSSIEC (app.main:app).
Ensures that even if GitHub web upload skips the 'app/' directory,
uploading 'app.py' automatically restores 'app/' and all templates/modules
when Render runs `uvicorn app.main:app --host 0.0.0.0 --port $PORT`.
"""
import os
import io
import zipfile
import base64

_ROOT_DIR = os.path.dirname(os.path.abspath(__file__))
_APP_DIR = os.path.join(_ROOT_DIR, "app")

_BUNDLE_B64 = ""

def _ensure_app_extracted():
    main_py = os.path.join(_APP_DIR, "main.py")
    cert_html = os.path.join(_APP_DIR, "templates", "election_certificate.html")
    pdf_gen = os.path.join(_APP_DIR, "pdf_generator.py")
    if not (os.path.exists(main_py) and os.path.exists(cert_html) and os.path.exists(pdf_gen)):
        raw = base64.b64decode(_BUNDLE_B64)
        with zipfile.ZipFile(io.BytesIO(raw), "r") as zf:
            zf.extractall(_ROOT_DIR)

_ensure_app_extracted()

# Mark this module as a package pointing to the './app' directory
__path__ = [_APP_DIR]
